  const NEIGHBORHOODS = [{"name": "Plaka", "desc": "The quarter the city never left, at its best before the first coach parks", "maps": "https://www.google.com/maps/search/?api=1&query=Plaka+Athens"}, {"name": "Monastiraki", "desc": "A monastery, a mosque and Hadrian's library in one glance, and the flea market every Sunday", "maps": "https://www.google.com/maps/search/?api=1&query=Monastiraki+Square+Athens"}, {"name": "Psyrri", "desc": "Hammers in the morning, bouzouki at night, and the walls painted in between", "maps": "https://www.google.com/maps/search/?api=1&query=Psyrri+Athens"}, {"name": "Exarcheia", "desc": "The Polytechnic's quarter: radical presses, record shops and a square still under metro works", "maps": "https://www.google.com/maps/search/?api=1&query=Exarcheia+Athens"}, {"name": "Metaxourgeio and Kerameikos", "desc": "A silk mill gave it the name; galleries, wholesalers and an ancient cemetery share it now", "maps": "https://www.google.com/maps/search/?api=1&query=Avdi+Square+Metaxourgeio+Athens"}, {"name": "Kolonaki", "desc": "Embassies, tailors and two great museums on the slope of Lycabettus; a salon, not a kitchen", "maps": "https://www.google.com/maps/search/?api=1&query=Kolonaki+Square+Athens"}, {"name": "Pangrati", "desc": "Behind the marble stadium, the residential quarter that cooks harder than any other in Athens", "maps": "https://www.google.com/maps/search/?api=1&query=Plateia+Varnava+Pangrati+Athens"}, {"name": "Koukaki", "desc": "A working grid below Filopappou that short lets have hollowed out, its café streets still standing", "maps": "https://www.google.com/maps/search/?api=1&query=Koukaki+Athens"}, {"name": "Ano Petralona", "desc": "Bitter-orange trees, low pastel houses and the most honest tavernas in the centre", "maps": "https://www.google.com/maps/search/?api=1&query=Troon+Ano+Petralona+Athens"}, {"name": "Kypseli", "desc": "Art Deco lobbies, Ghanaian barbers and new coffee bars along one long garden promenade", "maps": "https://www.google.com/maps/search/?api=1&query=Fokionos+Negri+Kypseli+Athens"}];
  const WALKS = [{"name": "The Pikionis paths of Philopappou", "desc": "A path laid stone by stone from the rubble of old Athens, with the Parthenon framed at every turn", "maps": "https://www.google.com/maps/search/?api=1&query=Philopappos+Monument+Athens"}, {"name": "Dionysiou Areopagitou, the grand promenade", "desc": "A marble avenue along the whole south slope of the Acropolis, open to walkers since the 2000s", "maps": "https://www.google.com/maps/search/?api=1&query=Dionysiou+Areopagitou+Athens"}, {"name": "Anafiotika at dawn", "desc": "A cluster of island houses built by stonemasons from Anafi, high on the Acropolis rock", "maps": "https://www.google.com/maps/search/?api=1&query=Anafiotika+Plaka+Athens"}, {"name": "Kerameikos to Gazi", "desc": "The potters' cemetery, just reopened after three years of works, then the gasworks 400 m away", "maps": "https://www.google.com/maps/search/?api=1&query=Kerameikos+Archaeological+Site+Athens"}, {"name": "Kaisariani monastery and the Hymettus pines", "desc": "An eleventh-century monastery in a pine fold of Hymettus, half an hour from Syntagma", "maps": "https://www.google.com/maps/search/?api=1&query=Kaisariani+Monastery+Athens"}, {"name": "Athens Riviera, Flisvos to Edem", "desc": "Five flat kilometres of sea path, from a 1911 armoured cruiser to the yacht berths and the city beach", "maps": "https://www.google.com/maps/search/?api=1&query=Battleship+Averof+Trocadero+Palaio+Faliro+Athens"}];
  const WORK_SPOTS = [{"name": "Athénée (ex-Zonars)", "desc": "The grand café that lost its name in court, and kept its 1939 mosaic floor", "maps": "https://www.google.com/maps/search/?api=1&query=Ath%C3%A9n%C3%A9e+Voukourestiou+9+Athens"}, {"name": "Winter Garden — Hotel Grande Bretagne", "desc": "Tea under a stained-glass ceiling, the nearest Athens comes to a Viennese salon", "maps": "https://www.google.com/maps/search/?api=1&query=Hotel+Grande+Bretagne+Winter+Garden+Athens"}, {"name": "Nummus — Numismatic Museum garden café", "desc": "The calmest garden coffee near Syntagma, and in summer it is over by 15:30", "maps": "https://www.google.com/maps/search/?api=1&query=Numismatic+Museum+Garden+Cafe+Athens"}, {"name": "Black Duck Garden — Athens City Museum bistrot", "desc": "A royal garden sixty metres off Stadiou, where the traffic gives way to birds", "maps": "https://www.google.com/maps/search/?api=1&query=Black+Duck+Garden+Athens+City+Museum+Athens"}, {"name": "National Library reading rooms", "desc": "The best free desk in Attica: plugs, Wi-Fi and silence, open till midnight", "maps": "https://www.google.com/maps/search/?api=1&query=National+Library+of+Greece+SNFCC+Athens"}, {"name": "Okupa", "desc": "Hostel, co-working desks and a kitchen under one Kerameikos roof", "maps": "https://www.google.com/maps/search/?api=1&query=Okupa+Psaromiligkou+9+Athens"}, {"name": "Kick", "desc": "Part café, part co-working room, part gallery, built to be sat in", "maps": "https://www.google.com/maps/search/?api=1&query=Kick+Sporadon+26+Kypseli+Athens"}, {"name": "Dexameni", "desc": "Kolonaki's old literary kafeneio: order an ouzo and the plane-tree table is yours all evening", "maps": "https://www.google.com/maps/search/?api=1&query=Dexameni+Kolonaki+Athens"}, {"name": "Taf Coffee", "desc": "The 2009 bar credited with starting Athens' specialty coffee, cup first", "maps": "https://www.google.com/maps/search/?api=1&query=Taf+Coffee+Emmanouil+Benaki+7+Athens"}];
